  "bools" = { {
      "name" = "dntStandingWaterForms",
      "value" = true,
      "comment" = "water underground is found as flowing water (brooks, streams, and rivers) and standing water (pools, reservoirs, lakes, and seas).",
    }, {
      "name" = "dntLowCeilingBlocksBoats",
      "value" = true,
      "comment" = "if the ceiling over an underground lake, pool, or sea touches the surface of the water or leaves only a few inches of clearance, normal boat travel is impossible.",
    }, {
      "name" = "dntNoWindSailingRare",
      "value" = true,
      "comment" = "the absence of wind means that sailing is virtually unheard-of underground, except in those rare instances where the ventilation is ample enough to create a wind capable of moving a boat.",
    }, {
      "name" = "dntWavesPracticallyNonexistent",
      "value" = true,
      "comment" = "waves are practically nonexistent underground; lake and sea shores are not eroded by wave action.",
    }, {
      "name" = "dntCaveInMakesTsunamiWave",
      "value" = true,
      "comment" = "a cave-in somewhere above or next to a lake often forces a powerful wave outward, much like a tsunami; earthquakes often produce similarly destructive waves in the Underdark.",
    }, {
      "name" = "dntChopAmplifiedByWalls",
      "value" = true,
      "comment" = "the action of waves is often amplified and confused by the confining walls: a large wave in a small body of water can last for many turns - the exact duration is left to the DM, depending on the force of the original wave and the size of the enclosing area.",
    }, {
      "name" = "dntWiseToFindWaveSource",
      "value" = true,
      "comment" = "other causes of waves include animal, monster, and humanoid activity, and streams flowing into a standing body; characters confronted with waves on otherwise still water are wise to determine the source of the disturbance.",
    }, {
      "name" = "dntLakesPoolsFreshWater",
      "value" = true,
      "comment" = "lakes and pools make up the majority of underground bodies of water; they differ in size (lakes are larger) but both contain fresh water, and can be found at nearly all depths of the Underdark.",
    }, {
      "name" = "dntInflowWaterSafeToDrink",
      "value" = true,
      "comment" = "if a lake or pool has a stream or spring flowing into it, the water is almost always safe to drink.",
    }, {
      "name" = "dntReservoirDamMayBeAtBottom",
      "value" = true,
      "comment" = "reservoirs are commonly created by intelligent denizens; the dam is not always built along the side - it may be located at the bottom, serving much the same function as a cork in the bottom of a leaky bucket.",
    }, {
      "name" = "dntSeasDeepSaltHuge",
      "value" = true,
      "comment" = "seas lie in the deepest depths of the Underdark: salty water heavy with minerals dissolved from the surrounding rock, and almost always huge in comparison to other underground bodies of water because of their age.",
    }, {
      "name" = "dntSeasGeothermalSteam",
      "value" = true,
      "comment" = "whole races inhabit the seas of the Underdark; some seas are cold, vast, and deep, while others lie so close to geothermal heat sources that their waters are warm and the surrounding air is heavy with steam.",
    }, {
      "name" = "dntFlowingMoreCommonThanStanding",
      "value" = true,
      "comment" = "flowing water is more commonly encountered underground than standing water - it is flowing water that has shaped much of the underground environment.",
    }, {
      "name" = "dntThreeMeasurements",
      "value" = true,
      "comment" = "the characteristics of a flowing body of water are determined by three significant measurements: the diameter of the waterway, the percentage of the passage that is filled with water, and the rate of flow.",
    }, {
      "name" = "dntArtificialCanalsAqueducts",
      "value" = true,
      "comment" = "artificially constructed underground waterways include canals for water transportation and aqueducts moving water from one location to another; the underground races also use flowing water to turn water wheels powering fans, pumps, and other machinery, and water-powered pumps even operate locks on underground canals.",
    }, {
      "name" = "dntFullFlowUnboatable",
      "value" = true,
      "comment" = "a passage with 100% flow is completely filled with water and impossible to boat through.",
    }, {
      "name" = "dntStagnantShallowBoatRisk",
      "value" = true,
      "comment" = "travel along stagnant water is not threatened by flow, but it may be difficult if the water is too shallow to support a boat.",
    }, {
      "name" = "dntPlacidFloatersShowFlow",
      "value" = true,
      "comment" = "placid water sometimes requires dropping bits of wood, dust, or other floating objects into the water to determine the direction of its flow.",
    }, {
      "name" = "dntMediumWatchForRocks",
      "value" = true,
      "comment" = "travel along a medium waterway is relatively safe, but characters must keep a lookout for rocks protruding from the water; the inattentive may be drawn into an unfortunate collision by the force of the flow.",
    }, {
      "name" = "dntRapidsUpstreamImpossible",
      "value" = true,
      "comment" = "traveling upstream along rapids is impossible unless powerful magic is employed; traveling downstream is dangerous, but possible.",
    }, {
      "name" = "dntRapidsNeedBoatingProficiency",
      "value" = true,
      "comment" = "certain boats such as kayaks are more suited to rapids than most standard boats; characters who boat down a rapid stream without boating proficiency will find themselves in great danger.",
    }, {
      "name" = "dntCascadeUpstreamImpossible",
      "value" = true,
      "comment" = "traveling upstream against the force of a cascade is impossible; traveling downstream might be possible for a lucky character with boating proficiency in a kayak.",
    }, {
      "name" = "dntWaterfallStretchesWithRapids",
      "value" = true,
      "comment" = "a long stretch of waterfalls, with rapids or cascades between them, is still considered a waterfall.",
    }, {
      "name" = "dntWaterfallBoatUncontrollable",
      "value" = true,
      "comment" = "the nature of a waterfall makes it impossible to control a boat traveling over the fall; survival is more a matter of luck than skill.",
    }, {
      "name" = "dntDamBacksUpFloods",
      "value" = true,
      "comment" = "a dammed underground waterway immediately begins to back up and flood behind the dam; the DM must rely on accurate three-dimensional maps (see DSG page 114), as the water may be diverted into other parts of the setting, filling rooms and making its way through corridors and down stairways.",
    }, {
      "name" = "dntDamDoubleWideQuarterNarrow",
      "value" = true,
      "comment" = "the backup figure is doubled for a wide waterway and quartered for a narrow one.",
    }, {
      "name" = "dntDamDivertsLeastResistance",
      "value" = true,
      "comment" = "as soon as the water level reaches a height that allows it to flow through another channel, it changes course to follow the path of least resistance.",
    }, {
      "name" = "dntDamCurrentDestroysFlow",
      "value" = true,
      "comment" = "the current destroys a number of dam points equal to the water rate of flow each turn, so several characters must work together to dam rapid streams.",
    }, {
      "name" = "dntDamCompletedStable",
      "value" = true,
      "comment" = "once a dam is completed, water will not destroy it unless something specifically weakens the dam or increases the water pressure.",
    }, {
      "name" = "dntUndergroundWaterUniversallyCold",
      "value" = true,
      "comment" = "unless some external source of heat contributes, underground water is almost universally cold; it rarely freezes underground, but its temperature is numbing to any characters who get soaked in it.",
    }, {
      "name" = "dntGeothermalWarming",
      "value" = true,
      "comment" = "underground water can occasionally be warmed by geothermal heat sources - the same energy that gives rise to geysers and volcanoes; depending on proximity the water might be only slightly warmer, or hot enough to scald a character to death very quickly.",
    }, {
      "name" = "dntBoilingNoSave",
      "value" = true,
      "comment" = "no saving throw is allowed against the near-boiling 6d6 burn damage per round, though magical protection against heat or fire gains a -2 per die (minimum 1 point per die).",
    }, {
      "name" = "dntBoilingPartialProportional",
      "value" = true,
      "comment" = "characters only partially immersed in near-boiling water suffer partial damage: the DM establishes a proportional number of d6 based on what proportion of their bodies is exposed.",
    }, {
      "name" = "dntVeryHotProtectedUnaffected",
      "value" = true,
      "comment" = "against the very-hot (not near-boiling) 1d6 damage, characters only partially exposed or with any magical protection against fire and heat attacks are not affected.",
    }, {
      "name" = "dntBathWarmNoIllEffects",
      "value" = true,
      "comment" = "if the water is no warmer than very hot bath water, characters suffer no ill effects from the heat.",
    }, {
      "name" = "dntDirectSurfaceEmbarkOccasional",
      "value" = true,
      "comment" = "the streams and lakes of the Underdark can occasionally be embarked upon directly from the surface: a meandering stream may flow into a cave and disappear, or the far side of a mountain lake may include a cave high enough and deep enough for a boat to enter.",
    }, {
      "name" = "dntUsuallyEnterViaDungeon",
      "value" = true,
      "comment" = "more often, water drops from the surface in cascades and waterfalls, or trickles through a tunnel too narrow to follow; characters must enter the underearth through a dungeon or cavern and find a suitable place to join the river below.",
    }, {
      "name" = "dntOutletRequiresUpstream",
      "value" = true,
      "comment" = "in rare cases an underground river returns to the surface; if the water is suitably placid, such an outlet can provide access to an underground waterway, but entering at a water outlet necessarily entails the problems of traveling upstream along the water.",
    }, {
      "name" = "dntLakeShoresCliffsNotSand",
      "value" = true,
      "comment" = "underground lakes and seas are generally not surrounded by sandy beaches - without waves there is no force to grind the stone into sand; such bodies are more likely surrounded by sheer cliffs or jagged boulders, though inhabited portions may hold creature-built docks or wharves, possibly with a few boats lying around.",
    }, {
      "name" = "dntStreamShoresSandBeaches",
      "value" = true,
      "comment" = "streams and rivers are much more likely to be bordered by smooth sand beaches that allow easy access to the water.",
    } },
